code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    boxes = []
    for color in range(1, 10):
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        if not cells:
            continue
        r0 = min(r for r, c in cells); r1 = max(r for r, c in cells)
        c0 = min(c for r, c in cells); c1 = max(c for r, c in cells)
        if r1-r0 < 2 or c1-c0 < 2:
            continue
        perimeter = {(r,c) for r in range(r0,r1+1) for c in range(c0,c1+1)
                     if r in (r0,r1) or c in (c0,c1)}
        if all(grid[r][c] == color for r,c in perimeter):
            boxes.append((color,r0,r1,c0,c1))
    frame_colors = {b[0] for b in boxes}
    counts = Counter(v for row in grid for v in row if v and v not in frame_colors)
    out = [[0]*w for _ in range(h)]
    assignments = []
    for fc,r0,r1,c0,c1 in boxes:
        interior_n = (r1-r0-1)*(c1-c0-1)
        checker_n = (interior_n+1)//2
        candidates = [color for color,n in counts.items() if n == checker_n]
        if not candidates:
            continue
        fill = candidates[0]
        assignments.append((fc,r0,r1,c0,c1,fill))
        for r in range(r0,r1+1):
            for c in range(c0,c1+1):
                if r in (r0,r1) or c in (c0,c1):
                    out[r][c] = fc
                elif (r-r0-1+c-c0-1)%2 == 0:
                    out[r][c] = fill
    return out
'''
